// Parse Anthropic response and extract JSON
const items = [];

for (const item of $input.all()) {
  try {
    const content = item.json.content;
    let textContent = '';

    if (Array.isArray(content) && content.length > 0) {
      textContent = content[0].text || '';
    } else if (typeof content === 'string') {
      textContent = content;
    }

    // Clean potential markdown code blocks
    textContent = textContent.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

    // Extract first valid JSON object
    const jsonMatch = textContent.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const parsed = JSON.parse(jsonMatch[0]);

      // Add original email data
      parsed.original_from = $('Normalize Email Data').item.json.from;
      parsed.original_subject = $('Normalize Email Data').item.json.subject;
      parsed.original_messageId = $('Normalize Email Data').item.json.messageId;
      parsed.original_date = $('Normalize Email Data').item.json.date;
      parsed.original_body = $('Normalize Email Data').item.json.body;

      // Generate thread_key if missing
      if (!parsed.thread_key) {
        const crypto = require('crypto');
        parsed.thread_key = crypto
          .createHash('md5')
          .update(parsed.original_from + parsed.original_subject)
          .digest('hex').substring(0, 16);
      }

      items.push({ json: parsed });
    } else {
      throw new Error('No valid JSON found in response');
    }
  } catch (error) {
    // Fallback: create minimal structure
    items.push({
      json: {
        intent: 'autre',
        language: 'fr',
        can_quote_now: false,
        error: error.message,
        reply_draft: '<p>Merci pour votre message. Nous reviendrons vers vous rapidement.</p>',
        original_from: $('Normalize Email Data').item.json.from,
        original_subject: $('Normalize Email Data').item.json.subject,
        original_messageId: $('Normalize Email Data').item.json.messageId
      }
    });
  }
}

return items;

// Calculate detailed quote based on pricing rules
const items = [];

for (const item of $input.all()) {
  const lead = item.json.lead || {};
  const service = (lead.service_demande || '').toLowerCase();
  const description = (lead.description_projet || '').toLowerCase();
  const budget = lead.budget_montant || 0;

  // Pricing grid (easy to edit)
  const pricing = {
    "site_vitrine": {
      "base": 2500,
      "per_page": 300,
      "cms": 800,
      "seo_base": 500,
      "forms": 400
    },
    "ecommerce": {
      "base": 5000,
      "per_product_category": 500,
      "payment_integration": 800,
      "shipping": 600
    },
    "seo": {
      "audit": 800,
      "onpage_monthly": 600,
      "content_monthly": 400,
      "backlinks_monthly": 800
    },
    "agent_ia": {
      "email_automation": 1500,
      "crm_integration": 1200,
      "chatbot": 2000,
      "custom_workflow": 2500
    }
  };

  const lines = [];
  let subtotal = 0;

  // Auto-detect service and build quote
  if (service.includes('site') || service.includes('web') || description.includes('site')) {
    // Site vitrine detected
    const pages = parseInt(description.match(/(\d+)\s*page/i)?.[1] || '5');
    lines.push({
      description: `Site vitrine (${pages} pages)`,
      quantity: 1,
      unit_price: pricing.site_vitrine.base + (pages * pricing.site_vitrine.per_page),
      total: pricing.site_vitrine.base + (pages * pricing.site_vitrine.per_page)
    });

    if (description.includes('cms') || description.includes('wordpress')) {
      lines.push({
        description: 'CMS / Administration',
        quantity: 1,
        unit_price: pricing.site_vitrine.cms,
        total: pricing.site_vitrine.cms
      });
    }

    if (description.includes('seo') || service.includes('seo')) {
      lines.push({
        description: 'SEO de base (optimisation on-page)',
        quantity: 1,
        unit_price: pricing.site_vitrine.seo_base,
        total: pricing.site_vitrine.seo_base
      });
    }

    if (description.includes('formulaire') || description.includes('contact')) {
      lines.push({
        description: 'Formulaires personnalisés',
        quantity: 1,
        unit_price: pricing.site_vitrine.forms,
        total: pricing.site_vitrine.forms
      });
    }
  }

  if (service.includes('seo') && !service.includes('site')) {
    lines.push({
      description: 'Audit SEO complet',
      quantity: 1,
      unit_price: pricing.seo.audit,
      total: pricing.seo.audit
    });

    if (description.includes('mensuel') || description.includes('monthly') || description.includes('recurring')) {
      lines.push({
        description: 'Optimisation on-page (mensuel)',
        quantity: 3,
        unit_price: pricing.seo.onpage_monthly,
        total: pricing.seo.onpage_monthly * 3
      });
    }
  }

  if (service.includes('agent') || service.includes('ia') || service.includes('automation')) {
    if (description.includes('email') || description.includes('mail')) {
      lines.push({
        description: 'Agent IA Email (workflow complet)',
        quantity: 1,
        unit_price: pricing.agent_ia.email_automation,
        total: pricing.agent_ia.email_automation
      });
    }

    if (description.includes('crm')) {
      lines.push({
        description: 'Intégration CRM',
        quantity: 1,
        unit_price: pricing.agent_ia.crm_integration,
        total: pricing.agent_ia.crm_integration
      });
    }

    if (description.includes('chatbot') || description.includes('chat')) {
      lines.push({
        description: 'Chatbot IA personnalisé',
        quantity: 1,
        unit_price: pricing.agent_ia.chatbot,
        total: pricing.agent_ia.chatbot
      });
    }

    if (!lines.length) {
      // Default automation workflow
      lines.push({
        description: 'Workflow d\'automatisation personnalisé',
        quantity: 1,
        unit_price: pricing.agent_ia.custom_workflow,
        total: pricing.agent_ia.custom_workflow
      });
    }
  }

  // Fallback if no service detected
  if (lines.length === 0) {
    lines.push({
      description: 'Projet sur mesure',
      quantity: 1,
      unit_price: Math.max(budget * 0.8, 2000),
      total: Math.max(budget * 0.8, 2000)
    });
  }

  // Calculate totals
  subtotal = lines.reduce((sum, line) => sum + line.total, 0);
  const tva_rate = 0.077; // 7.7% Swiss VAT
  const tva_amount = subtotal * tva_rate;
  const total_ttc = subtotal + tva_amount;

  // Delivery time estimation
  const delai = lead.delai_souhaite || 'À déterminer';
  const estimated_weeks = Math.ceil(subtotal / 800); // ~800 CHF/week

  // Quote object
  const quote = {
    quote_number: `LXS-${Date.now().toString().slice(-8)}`,
    date: new Date().toISOString().split('T')[0],
    client: {
      nom: lead.nom || '',
      prenom: lead.prenom || '',
      entreprise: lead.entreprise || '',
      email: lead.email,
      telephone: lead.telephone || ''
    },
    lines: lines,
    subtotal_ht: subtotal.toFixed(2),
    tva_rate: (tva_rate * 100).toFixed(1),
    tva_amount: tva_amount.toFixed(2),
    total_ttc: total_ttc.toFixed(2),
    devise: lead.budget_devise || 'CHF',
    delai_souhaite: delai,
    delai_estime: `${estimated_weeks} semaines`,
    validite: '30 jours',
    conditions: [
      'Acompte de 30% à la commande',
      'Solde à la livraison',
      'Délai de paiement: 15 jours net',
      'Support 3 mois inclus'
    ],
    description_projet: lead.description_projet || ''
  };

  items.push({
    json: {
      ...item.json,
      quote: quote
    }
  });
}

return items;

